import{_ as r,a8 as e,o as l,c as n,ah as i,K as d}from"./chunks/framework.BUAh2RRO.js";import"./chunks/theme.-p-ond56.js";const f=JSON.parse('{"title":"子弹笔记","description":"","frontmatter":{"title":"子弹笔记","abstract":"子弹笔记的符号系统、四大核心集子与「结论第一」原则，用一套快速记录与迁移机制管理待办、事件与灵感。","created":"2026-07-02T00:00:00.000Z","tags":["笔记方法","效率","时间管理"],"type":"概念解释","related":["[[📚 个人知识管理-MOC]]","[[笔记方法七合一|笔记方法七合一：双支柱场景演练]]"],"reference":null,"category":["📚 个人知识管理","个人能力"]},"headers":[],"relativePath":"vault/Knowledge/Methods/子弹笔记.md","filePath":"vault/Knowledge/Methods/子弹笔记.md","lastUpdated":1790655645000}'),s={name:"vault/Knowledge/Methods/子弹笔记.md"};function c(h,t,_,b,g,p){const a=e("NolebaseGitContributors"),o=e("NolebaseGitChangelog");return l(),n("div",null,[t[0]||(t[0]=i('<h1 id="子弹笔记" tabindex="-1">子弹笔记 <a class="header-anchor" href="#子弹笔记" aria-label="Permalink to “子弹笔记”">​</a></h1><h2 id="一句话概述" tabindex="-1">一句话概述 <a class="header-anchor" href="#一句话概述" aria-label="Permalink to “一句话概述”">​</a></h2><p>子弹笔记（Bullet Journal）是用符号系统快速记录、组织和追踪信息的方法论，核心原则是<strong>结论第一</strong>——重点/目标放最前面，再展开细节。</p><h2 id="核心符号系统" tabindex="-1">核心符号系统 <a class="header-anchor" href="#核心符号系统" aria-label="Permalink to “核心符号系统”">​</a></h2><table tabindex="0"><thead><tr><th>符号</th><th>含义</th><th>说明</th></tr></thead><tbody><tr><td><code>·</code></td><td>任务</td><td>待办事项</td></tr><tr><td><code>×</code></td><td>已完成</td><td>任务完成后将 <code>·</code> 改为 <code>×</code></td></tr><tr><td><code>&gt;</code></td><td>迁移</td><td>推迟到后续处理</td></tr><tr><td><code>&lt;</code></td><td>计划中</td><td>已排入日程</td></tr><tr><td><code>○</code></td><td>事件</td><td>发生的事，不是任务</td></tr><tr><td><code>-</code></td><td>笔记</td><td>事实、想法、观察</td></tr><tr><td><code>*</code></td><td>优先级</td><td>重要事项</td></tr><tr><td><code>!</code></td><td>灵感</td><td>值得扩展的想法</td></tr></tbody></table><h2 id="四大核心集子" tabindex="-1">四大核心集子 <a class="header-anchor" href="#四大核心集子" aria-label="Permalink to “四大核心集子”">​</a></h2><ol><li><strong>索引（Index）</strong>：目录页，标注每个集子的页码</li><li><strong>未来记录（Future Log）</strong>：年度概览，记录未来月份的事项</li><li><strong>月度记录（Monthly Log）</strong>：当月日历 + 任务清单</li><li><strong>每日记录（Daily Log）</strong>：当天的事项，快速记录</li></ol><h2 id="结论第一原则" tabindex="-1">结论第一原则 <a class="header-anchor" href="#结论第一原则" aria-label="Permalink to “结论第一原则”">​</a></h2><blockquote><p>笔记、汇报、记录——把<strong>重点、目的、目标</strong>放最前面，之后再写步骤或原因。</p></blockquote><p>前提是你知道这件事的来龙去脉。这不是省略思考，而是让读者/未来的自己能快速定位核心信息。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h2><ul><li>快节奏的技术工作中管理待办和信息流</li><li>会议纪要：结论前置，细节后置</li><li>学习笔记：先概括核心，再展开论证</li></ul>',12)),d(a),d(o)])}const x=r(s,[["render",c]]);export{f as __pageData,x as default};
